import { test, expect } from '@playwright/test';

test.describe('Public Profile Page - Shared Information Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile/user123');
  });

  test('should display user profile with shared information when logged in', async ({ page }) => {
    // Verify profile page title is visible
    const profileTitle = page.getByRole('heading', { name: /user profile/i });
    await expect(profileTitle).toBeVisible();

    // Verify user name is displayed using getByRole
    const userName = page.getByRole('heading', { name: /john doe/i });
    await expect(userName).toBeVisible();

    // Verify bio is displayed using getByText
    const userBio = page.getByText(/senior developer and writer/i);
    await expect(userBio).toBeVisible();

    // Verify profile picture is displayed using getByLabel
    const profilePic = page.getByLabel(/profile picture/i);
    await expect(profilePic).toBeVisible();

    // Verify contact email is displayed using getByText
    const contactEmail = page.getByText(/john.doe@example.com/i);
    await expect(contactEmail).toBeVisible();

    // Verify website link is displayed using getByText
    const websiteLink = page.getByText(/johnsmith.com/i);
    await expect(websiteLink).toBeVisible();

    // Verify social media links are present using getByRole
    const twitterLink = page.getByRole('link', { name: /twitter/i });
    await expect(twitterLink).toBeVisible();

    const linkedinLink = page.getByRole('link', { name: /linkedin/i });
    await expect(linkedinLink).toBeVisible();

    // Verify profile is marked as public
    const publicStatus = page.getByText(/public profile/i);
    await expect(publicStatus).toBeVisible();
  });

  test('should handle missing shared information gracefully', async ({ page }) => {
    // Navigate to a profile with minimal shared data
    await page.goto('/profile/user444');

    // Verify profile page loads
    const profileTitle = page.getByRole('heading', { name: /user profile/i });
    await expect(profileTitle).toBeVisible();

    // Verify user name is displayed
    const userName = page.getByRole('heading', { name: /jane smith/i });
    await expect(userName).toBeVisible();

    // Verify bio placeholder is displayed when bio is missing
    const bioPlaceholder = page.getByText(/no bio available/i);
    await expect(bioPlaceholder).toBeVisible();

    // Verify contact email placeholder is displayed
    const emailPlaceholder = page.getByText(/contact information not shared/i);
    await expect(emailPlaceholder).toBeVisible();

    // Verify website link placeholder is displayed
    const websitePlaceholder = page.getByText(/website not available/i);
    await expect(websitePlaceholder).toBeVisible();

    // Verify social media links are not displayed when not shared
    const twitterLink = page.getByRole('link', { name: /twitter/i });
    await expect(twitterLink).not.toBeVisible();

    const linkedinLink = page.getByRole('link', { name: /linkedin/i });
    await expect(linkedinLink).not.toBeVisible();

    // Verify public status is still visible
    const publicStatus = page.getByText(/public profile/i);
    await expect(publicStatus).toBeVisible();
  });
});
